@register.simple_tag
def icon(name, cls="h-5 w-5"):
    d = PATHS.get(name, PATHS["home"])
    if name == "whatsapp":
        return format_html('<svg class="{} flex-none" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="{}"/></svg>', cls, d)
    return format_html('<svg class="{} flex-none" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path stroke-linecap="round" stroke-linejoin="round" d="{}"/></svg>', cls, d)


@register.filter
def get_item(d, key):
    return (d or {}).get(key)


@register.filter
def kes(value):
    """1500 -> '1,500'; 1500.5 -> '1,500.50'"""
    try:
        v = float(value or 0)
    except (TypeError, ValueError):
        return value
    return f"{v:,.0f}" if v == int(v) else f"{v:,.2f}"


@register.filter
def split_str(value, sep=","):
    return [x.strip() for x in str(value).split(sep)]
